INSERT INTO `guided_steps` (`lesson_id`, `step_order`, `prompt`, `correct_snippet`, `distractor_1`, `distractor_2`, `distractor_3`) VALUES
(199, 1, 'Which code prints 4321 with a while loop and then stops?', 'int i = 4; while (i > 0) { System.out.print(i); i--; }', 'int i = 4; while (i > 0) { System.out.print(i); }', 'int i = 4; while (i > 0) { System.out.print(i); i++; }', 'int i = 4; while i > 0 { System.out.print(i); i--; }'),
(200, 1, 'Which loop prints 123 and then terminates?', 'int count = 1; while (count <= 3) { System.out.print(count); count++; }', 'int count = 1; while (count <= 3) { System.out.print(count); }', 'int count = 1; while (count <= 3) { System.out.print(count); count--; }', 'int count = 1; while (count >= 3) { System.out.print(count); count++; }'),
(201, 1, 'Which do-while loop prints 012?', 'int i = 0; do { System.out.print(i); i++; } while (i < 3);', 'int i = 0; do { System.out.print(i); i++; } while (i < 3)', 'int i = 0; do { System.out.print(i); i++; } until (i < 3);', 'int i = 0; do while (i < 3) { System.out.print(i); i++; }'),
(202, 1, 'Which loop prints Once exactly one time even though i < 5 is false?', 'int i = 10; do { System.out.println("Once"); } while (i < 5);', 'int i = 10; while (i < 5) { System.out.println("Once"); }', 'int i = 10; do { System.out.println("Once"); } while (i > 5);', 'int i = 10; do { System.out.println("Once"); } while (i < 5)'),
(203, 1, 'Which for loop prints the numbers 0 to 9?', 'int i; for (i = 0; i < 10; i++) { System.out.print(i); }', 'int i; for (i = 0, i < 10, i++) { System.out.print(i); }', 'int i; for (i = 0; i < 10) { System.out.print(i); }', 'int i; for (i = 0; i > 10; i++) { System.out.print(i); }'),
(204, 1, 'Which while loop does the same as for (i = 0; i < 10; i++) printing i?', 'int i = 0; while (i < 10) { System.out.print(i); i++; }', 'int i = 0; while (i < 10) { i++; System.out.print(i); }', 'int i = 0; while (i < 10) { System.out.print(i); }', 'int i = 0; while (i <= 10) { System.out.print(i); i++; }'),
(205, 1, 'Which for loop prints 54321?', 'for (int i = 5; i > 0; i--) { System.out.print(i); }', 'for (int i = 5; i > 0; i++) { System.out.print(i); }', 'for (int i = 5; i < 0; i--) { System.out.print(i); }', 'for (int i = 5; i > 0; i--;) { System.out.print(i); }'),
(206, 1, 'Which for loop prints 02468?', 'for (int i = 0; i < 10; i += 2) { System.out.print(i); }', 'for (int i = 0; i < 10; i + 2) { System.out.print(i); }', 'for (int i = 0; i < 10; i =+ 2) { System.out.print(i); }', 'for (int i = 0; i < 10; i += 2;) { System.out.print(i); }'),
(207, 1, 'Which loop stops completely as soon as i is 5?', 'for (int i = 0; i < 10; i++) { if (i == 5) { break; } }', 'for (int i = 0; i < 10; i++) { if (i = 5) { break; } }', 'for (int i = 0; i < 10; i++) { if (i == 5) { stop; } }', 'for (int i = 0; i < 10; i++) { if (i == 5) { continue; } }'),
(208, 1, 'Which loop sets foundName to true and stops searching when the name is found?', 'for (int i = 0; i < names.length; i++) { if (names[i].equals(searchName)) { foundName = true; break; } }', 'for (int i = 0; i < names.length(); i++) { if (names[i].equals(searchName)) { foundName = true; break; } }', 'for (int i = 0; i < names.length; i++) { if (names[i].equals(searchName)) { foundName = true; continue; } }', 'for (int i = 0; i < names.length; i++) { if (names[i].equals(searchName)) { foundName = true; break } }'),
(209, 1, 'Which loop uses break to leave a while (true) loop when i reaches 3?', 'int i = 0; while (true) { i++; if (i == 3) { break; } }', 'int i = 0; while (true) { i++; if (i == 3) { } }', 'int i = 0; while (true) { i++; if (i == 3) { break } }', 'int i = 0; while (false) { i++; if (i == 3) { break; } }'),
(210, 1, 'Which loop prints 0134?', 'for (int i = 0; i < 5; i++) { if (i == 2) { continue; } System.out.print(i); }', 'for (int i = 0; i < 5; i++) { if (i == 2) { break; } System.out.print(i); }', 'for (int i = 0; i < 5; i++) { if (i == 2) { continue; System.out.print(i); } }', 'for (int i = 0; i < 5; i++) { if (i == 2) { continue } System.out.print(i); }'),
(211, 1, 'Which loop counts only the names equal to "Beah"?', 'for (int i = 0; i < names.length; i++) { if (!names[i].equals("Beah")) { continue; } count++; }', 'for (int i = 0; i < names.length; i++) { if (names[i].equals("Beah")) { continue; } count++; }', 'for (int i = 0; i < names.length; i++) { if (!names[i].equals("Beah")) { break; } count++; }', 'for (int i = 0; i < names.length(); i++) { if (!names[i].equals("Beah")) { continue; } count++; }'),
