(213, 1, 'Which code jumps to the next pass of the outer loop when j == 2?', 'outerLoop: for (int i = 0; i < 5; i++) { for (int j = 0; j < 5; j++) { if (j == 2) { continue outerLoop; } } }', 'outerLoop: for (int i = 0; i < 5; i++) { for (int j = 0; j < 5; j++) { if (j == 2) { continue; } } }', 'outerLoop: for (int i = 0; i < 5; i++) { for (int j = 0; j < 5; j++) { if (j == 2) { continue: outerLoop; } } }', 'outerLoop: for (int i = 0; i < 5; i++) { for (int j = 0; j < 5; j++) { if (j == 2) { continue outerloop; } } }'),
(214, 1, 'Which method correctly returns the String "Hello"?', 'static String greet() { return "Hello"; }', 'static String greet() { return Hello; }', 'static int greet() { return "Hello"; }', 'static String greet() { return "Hello" }'),
